<script setup>
import PaperProgress from './PaperProgress.vue';
import {ref,onMounted} from 'vue';import {api,loadCatalog} from './api';
const props=defineProps({route:String});const exam=decodeURIComponent(props.route.slice('/exam/'.length));const courses=ref([]),course=ref(''),papers=ref([]),terms=ref([]),term=ref(''),page=ref(1),total=ref(0),loading=ref(false),error=ref('');
onMounted(async()=>{try{const catalog=await loadCatalog();courses.value=catalog.courses.filter(x=>x.exams?.[exam]);terms.value=catalog.meta.terms}catch(e){error.value=e.message}});
async function load(reset=true){if(reset)page.value=1;papers.value=[];total.value=0;if(!course.value)return;loading.value=true;error.value='';try{const d=await api('/papers?'+new URLSearchParams({exam,course_id:course.value,term_id:term.value,available:'true',page:page.value,limit:24}));papers.value=d.items;total.value=d.total}catch(e){error.value=e.message}finally{loading.value=false}}
</script>
<template><section class="exam-browser"><a href="#/" class="breadcrumb-link">Home → {{exam}}</a><div class="eyebrow mt-4">SELECT A COURSE</div><h1>{{exam}} previous-year papers</h1><p class="muted">Select your course to see papers ready for practice and exams.</p><p v-if="error" role="alert" class="alert alert-danger">{{error}}</p><div class="filters"><label>Course<select class="form-select" aria-label="Choose course" v-model="course" @change="load()"><option value="">Select course</option><option v-for="c in courses" :value="c.id">{{c.name}}</option></select></label><label>Term / Year<select class="form-select" aria-label="Choose term" v-model="term" @change="load()"><option value="">All available terms</option><option v-for="t in terms" :value="t.id">{{t.name}}</option></select></label></div><p v-if="loading" role="status">Loading papers…</p><p v-else-if="!course" class="empty panel">Choose a course above.</p><template v-else><h2>{{total}} available {{total===1?'paper':'papers'}}</h2><article v-for="p in papers" :key="p.id" class="paper-row panel"><div class="paper-info"><span class="eyebrow">{{p.term}} {{p.session}} · {{p.exam}}</span><h3>{{p.name}}</h3><PaperProgress :progress="p.progress"/><p class="muted small">{{p.question_count}} questions · {{p.total_marks??'—'}} marks</p></div><a class="btn btn-primary" :href="'#/paper/'+p.id">{{p.progress?.attempted?'Retake Test':'Take Test'}} →</a></article><p v-if="!loading&&!papers.length" class="empty panel">No extracted papers are available for this selection yet. The complete Excel catalog is still accessible from the course library.</p><div v-if="total>24" class="pagination-row"><button class="btn btn-light" :disabled="page===1" @click="page--;load(false)">Previous</button><span>Page {{page}}</span><button class="btn btn-light" :disabled="page*24>=total" @click="page++;load(false)">Next</button></div></template></section></template>
